solution:
def verify_rate(rows,claimed):
    w=sum(r.get('derived')=='WIN' for r in rows)
    l=sum(r.get('derived')=='LOSS' for r in rows)
    if w+l==0:
        return claimed is None
    return claimed is not None and abs(claimed-w/(w+l))<1e-9

